    'Vulnerability scanner' => 'Сканер уязвимостей',
    'Sensitive file' => 'Конфиденциальный файл',
    'Malformed request' => 'Некорректный запрос',
    'WordPress probing' => 'Зондирование WordPress',
    'Virtual patch' => 'Виртуальный патч',
    'Sign-in attempts' => 'Попытки входа',
